export function listJobs(jobs, { openOnly = false } = {}) {
  return openOnly ? jobs.filter(job => !job.done) : jobs.slice();
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { listJobs } from '../src/jobs.js';
const rows = JSON.parse(readFileSync(new URL('../data/jobs.json', import.meta.url), 'utf8'));
test('default list is a fresh ordered copy', () => { assert.deepEqual(listJobs(rows), rows); assert.notEqual(listJobs(rows), rows); });
test('supported imported done values keep working', () => { assert.deepEqual(listJobs(rows, {openOnly:true}).map(x => x.id), ['false','zero','null','missing','empty','label']); });
